import React, { useState, useRef, useEffect } from "react";

const ClientForm = ({ onSave, existingTags = [] }) => {
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [phone, setPhone] = useState("");
  const [tags, setTags] = useState([]);
  const [tagInput, setTagInput] = useState("");
  const [showDropdown, setShowDropdown] = useState(false);
  const [filteredTags, setFilteredTags] = useState([]);
  const inputRef = useRef(null);

  // Filter existing tags based on input
  useEffect(() => {
    if (tagInput.trim()) {
      const filtered = existingTags.filter(tag => 
        tag.toLowerCase().includes(tagInput.toLowerCase()) && !tags.includes(tag)
      );
      setFilteredTags(filtered);
      setShowDropdown(filtered.length > 0);
    } else {
      setFilteredTags([]);
      setShowDropdown(false);
    }
  }, [tagInput, existingTags, tags]);

  const handleTagInputChange = (e) => {
    setTagInput(e.target.value);
  };

  const addTag = (tag) => {
    if (tag.trim() && !tags.includes(tag.trim())) {
      setTags([...tags, tag.trim()]);
      setTagInput("");
      setShowDropdown(false);
    }
  };

  const handleTagInputKeyDown = (e) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      if (tagInput.trim()) {
        addTag(tagInput);
      }
    } else if (e.key === 'Escape') {
      setShowDropdown(false);
      setTagInput("");
    }
  };

  const removeTag = (tagToRemove) => {
    setTags(tags.filter(tag => tag !== tagToRemove));
  };

  const selectFromDropdown = (tag) => {
    addTag(tag);
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    onSave({ name, email, phone, tags });
    setName("");
    setEmail("");
    setPhone("");
    setTags([]);
    setTagInput("");
    setShowDropdown(false);
  };

  return (
    <form className="space-y-2" onSubmit={handleSubmit}>
      <input className="border p-2 w-full" placeholder="Full Name" value={name} onChange={e => setName(e.target.value)} required />
      <input className="border p-2 w-full" placeholder="Email Address" value={email} onChange={e => setEmail(e.target.value)} required />
      <input className="border p-2 w-full" placeholder="Contact Number" value={phone} onChange={e => setPhone(e.target.value)} />
      <div>
        {TAGS.map(tag => (
          <label key={tag} className="mr-2">
            <input type="checkbox" checked={tags.includes(tag)} onChange={() => handleTagChange(tag)} /> {tag}
          </label>
        ))}
      </div>
      <button className="bg-blue-500 text-white px-3 py-1 rounded" type="submit">Save Client</button>
    </form>
  );
};

export default ClientForm;
